const rawReply = $input.first().json.choices?.[0]?.message?.content ?? '{}';
let result = { isCrisis: false, level: 'none', safeReply: null };

try {
  const clean = rawReply.replace(/```json|```/gi, '').trim();
  const parsed = JSON.parse(clean);
  const validLevels = ['none', 'low', 'medium', 'high'];
  result.level    = validLevels.includes(parsed.level) ? parsed.level : 'none';
  result.isCrisis = ['medium', 'high'].includes(result.level);
  result.safeReply = result.isCrisis ? (parsed.safeReply ?? null) : null;
} catch(e) {
  console.error('Crisis parse error:', e.message, '| Raw:', rawReply.substring(0, 200));
}

const webhookData = $('Webhook Crisis Check').first().json;
return [{ json: {
  user_id:    webhookData.body?.user_id ?? webhookData.user_id,
  message:    webhookData.body?.message ?? webhookData.message,
  isCrisis:   result.isCrisis,
  level:      result.level,
  safeReply:  result.safeReply,
  msg_hash:   btoa(encodeURIComponent((webhookData.body?.user_id ?? '') + ':' + (webhookData.body?.message ?? ''))).substring(0, 64)
}}];

